  ('intro', $j${"eyebrow":{"mn":"GuideOne","en":"GuideOne","ko":"GuideOne"},"title":{"mn":"GuideOne гэж юу вэ?","en":"What is GuideOne?","ko":"GuideOne은 어떤 곳인가요?"},"text":{"mn":"GuideOne нь Солонгос хэл сурах, БНСУ-д суралцах болон Солонгостой холбоотой хэрэгцээнд зориулсан боловсрол, зөвлөгөөний үйлчилгээг нэг дороос хүргэхийг зорьдог. Бид Солонгос дахь хамтран ажилладаг сургуулиуд руугаа суралцагчдыг зуучилдаг.","en":"GuideOne aims to bring together education and advisory services for learning Korean, studying in South Korea and other Korea-related needs — in one place. We place students at our partner schools in Korea.","ko":"GuideOne은 한국어 학습, 한국 유학, 그리고 한국과 관련된 다양한 필요를 위한 교육·상담 서비스를 한 곳에서 제공하는 것을 목표로 합니다. 한국의 협력 학교로 학생들의 유학을 연결합니다."},"items":[{"icon":"Languages","title":{"mn":"Солонгос хэл","en":"Korean language","ko":"한국어"},"text":{"mn":"Анхан шатнаас ахисан түвшин хүртэлх сургалт","en":"Courses from beginner to advanced","ko":"초급부터 고급까지의 강좌"}},{"icon":"MessagesSquare","title":{"mn":"Суралцах зөвлөгөө","en":"Study advice","ko":"유학 상담"},"text":{"mn":"Зорилгоо тодорхойлж, зөв сонголт хийхэд","en":"Clarify your goals and choose well","ko":"목표를 정하고 올바른 선택을 하도록"}},{"icon":"GraduationCap","title":{"mn":"Солонгост суралцах","en":"Study in Korea","ko":"한국 유학"},"text":{"mn":"Хамтрагч сургуулиуд руу зуучлал","en":"Placement at our partner schools","ko":"협력 학교로의 유학 연결"}},{"icon":"Smartphone","title":{"mn":"Солонгост ашиглах дугаар","en":"Korean phone number","ko":"한국 휴대폰 번호"},"text":{"mn":"Очихоосоо өмнө холбоотой байх","en":"Be connected before you arrive","ko":"도착 전부터 연결"},"isNew":true}]}$j$::jsonb),
