  ('servicesCopy', $j${"eyebrow":{"mn":"Үйлчилгээ","en":"Services","ko":"서비스"},"title":{"mn":"Хэлнээс цааш — Солонгос руу хийх аялалд тань","en":"Beyond language — for your journey to Korea","ko":"언어를 넘어, 한국으로 향하는 여정을 위해"},"comingSoon":{"mn":"Дэлгэрэнгүй удахгүй","en":"Details coming soon","ko":"세부 내용 곧 공개"},"soon":{"mn":"Тун удахгүй","en":"Coming soon","ko":"곧 오픈"},"text":{"mn":"Солонгостой холбоотой таны хэрэгцээнд зориулсан үйлчилгээнүүд.","en":"Services for everything you need on your way to Korea.","ko":"한국과 관련된 필요를 위한 서비스."},"course":{"title":{"mn":"Хэлний сургалт","en":"Korean courses","ko":"한국어 강좌"},"description":{"mn":"Анхан шатнаас TOPIK бэлтгэл хүртэлх Солонгос хэлний сургалт.","en":"Korean courses from beginner level to TOPIK preparation.","ko":"초급부터 TOPIK 대비까지의 한국어 강좌."},"cta":{"mn":"Сургалт үзэх","en":"View courses","ko":"강좌 보기"}},"soonTitle":{"mn":"Удахгүй нэмэгдэх үйлчилгээ","en":"More services coming soon","ko":"곧 추가될 서비스"}}$j$::jsonb),
