  ('process', $j${"eyebrow":{"mn":"Алхам алхмаар","en":"Step by step","ko":"단계별로"},"title":{"mn":"Солонгост суралцах зам","en":"Your path to studying in Korea","ko":"한국 유학으로 가는 길"},"text":{"mn":"Ерөнхий дараалал — алхам бүр таны нөхцөлөөс хамаарч өөр байж болно.","en":"A general outline — each step may differ depending on your situation.","ko":"일반적인 흐름이며, 각 단계는 개인 상황에 따라 달라질 수 있습니다."},"steps":[{"title":{"mn":"Зөвлөгөө авах","en":"Get advice","ko":"상담 받기"},"text":{"mn":"Сонирхол, нөхцөл байдлаа ярилцана.","en":"Talk through your interests and situation.","ko":"관심사와 상황을 이야기합니다."}},{"title":{"mn":"Зорилгоо тодорхойлох","en":"Define your goal","ko":"목표 설정"},"text":{"mn":"Юу, хэзээ, яагаад суралцахаа тодорхойлно.","en":"Decide what, when and why you'll study.","ko":"무엇을, 언제, 왜 공부할지 정합니다."}},{"title":{"mn":"Сургууль сонгох","en":"Choose a school","ko":"학교 선택"},"text":{"mn":"Зорилгодоо тохирох сургууль, хөтөлбөрийг харьцуулна.","en":"Compare schools and programs that fit.","ko":"목표에 맞는 학교와 과정을 비교합니다."}},{"title":{"mn":"Материал бүрдүүлэх","en":"Prepare documents","ko":"서류 준비"},"text":{"mn":"Шаардлагатай баримт бичгээ бэлтгэнэ.","en":"Gather the documents you need.","ko":"필요한 서류를 준비합니다."}},{"title":{"mn":"Өргөдөл гаргах","en":"Apply","ko":"지원하기"},"text":{"mn":"Сонгосон сургуульдаа өргөдлөө илгээнэ.","en":"Submit your application to your chosen school.","ko":"선택한 학교에 지원서를 제출합니다."}},{"title":{"mn":"Суралцах","en":"Start studying","ko":"유학 시작"},"text":{"mn":"Солонгост шинэ эхлэлээ тавина.","en":"Begin your new chapter in Korea.","ko":"한국에서 새로운 시작을 합니다."}}]}$j$::jsonb),
