도하거나 전화로 문의해 주세요."},"again":{"mn":"Шинэ мессеж","en":"New message","ko":"새 메시지"},"required":{"mn":"Заавал бөглөнө","en":"Required","ko":"필수"},"interests":[{"value":"course","label":{"mn":"Солонгос хэлний сургалт","en":"Korean course","ko":"한국어 강좌"}},{"value":"korea-study","label":{"mn":"Солонгост суралцах зуучлал","en":"Study in Korea consulting","ko":"한국 유학 컨설팅"}},{"value":"korea-number","label":{"mn":"Солонгост ашиглах дугаар холболт","en":"Korean phone number","ko":"한국 휴대폰 번호 개통"}},{"value":"other","label":{"mn":"Бусад","en":"Other","ko":"기타"}}]}}$j$::jsonb),
  ('footerCopy', $j${"description":{"mn":"Солонгос хэлний сургалт, БНСУ-д суралцах зөвлөгөө болон Солонгост ашиглах үйлчилгээ.","en":"Korean language courses, study-in-Korea consulting and services for life in Korea.","ko":"한국어 교육, 한국 유학 상담, 한국 생활을 위한 서비스."},"navigation":{"mn":"Холбоос","en":"Links","ko":"바로가기"},"help":{"mn":"Тусламж","en":"Help","ko":"도움말"},"contact":{"mn":"Холбоо барих","en":"Contact","ko":"연락처"},"social":{"mn":"Сошиал холбоос","en":"Follow us","ko":"소셜 미디어"},"rights":"All rights reserved."}$j$::jsonb),
  ('serviceDetailCopy', $j${"back":{"mn":"Нүүр хуудас руу буцах","en":"Back to home","ko":"홈으로"},"topicsTitle":{"mn":"Зөвлөхөөс асууж болох зүйлс","en":"What you can ask us about","ko":"상담 가능한 내용"},"detailsTitle":{"mn":"Үйлчилгээний мэдээлэл","en":"Service details","ko":"서비스 정보"},"pending":{"mn":"Удахгүй шинэчлэгдэнэ","en":"To be announced","ko":"곧 업데이트"},"pendingNote":{"mn":"Дэлгэрэнгүй нөхцөлийг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Please check the full terms with a GuideOne advisor.","ko":"자세한 조건은 GuideOne 상담사에게 문의해 주세요."},"ctaTitle":{"mn":"Асуух зүйл байна уу?","en":"Have a question?","ko":"궁금한 점이 있나요?"},"ctaText":{"mn":"Утсаар залгах эсвэл мессеж үлдээгээрэй.","en":"Give us a call or leave a message.","ko":"전화하시거나 메시지를 남겨 주세요."}}$j$::jsonb)
insert into public.courses (slug, glyph, name, level, description, duration, price, is_placeholder, sort_order) values
