insert into public.services (slug, icon, status, title, summary, description, topics, details, is_new, sort_order) values
  ('korea-study', 'GraduationCap', 'active', $j${"mn":"Солонгост суралцах зуучлал","en":"Study in Korea consulting","ko":"한국 유학 컨설팅"}$j$::jsonb, $j${"mn":"Солонгос дахь хамтрагч сургуулиуд руу суралцагчдыг зуучилж, сургууль, хөтөлбөр сонгоход тусална.","en":"We place students at our partner schools in Korea and help you choose a school and program.","ko":"한국 협력 학교로 유학을 연결하고 학교·프로그램 선택을 돕습니다."}$j$::jsonb, $j${"mn":"GuideOne нь Солонгос дахь хамтран ажилладаг сургуулиуд руугаа суралцагчдыг зуучилдаг. Сургууль, хөтөлбөр сонголт болон суралцахтай холбоотой дараагийн алхмуудаа тодорхойлоход тань тусална.","en":"GuideOne places students at its partner schools in South Korea. We help you choose a school and program and define your next steps.","ko":"GuideOne은 한국의 협력 학교로 학생들의 유학을 연결합니다. 학교·프로그램 선택과 유학 준비의 다음 단계를 함께 정리해 드립니다."}$j$::jsonb, $j${"mn":["GuideOne-ий хамтрагч сургуулиуд ба тэдгээрийн хөтөлбөр","Хэлний бэлтгэл болон зэргийн хөтөлбөрийн ялгаа","Зорилго, сонирхолдоо тохирох сургууль, мэргэжил","Бүрдүүлэх материалын ерөнхий жагсаалт","Өргөдөл гаргах хугацаа, дараалал","Солонгост очихын өмнөх бэлтгэл"],"en":["GuideOne's partner schools and their programs","Language programs vs. degree programs","Schools and majors that fit your goals","A general list of required documents","Application timelines and order of steps","Preparing before you leave for Korea"],"ko":["GuideOne 협력 학교와 프로그램","어학연수와 학위 과정의 차이","목표와 관심에 맞는 학교·전공","준비 서류의 일반적인 목록","지원 일정과 절차","출국 전 준비 사항"]}$j$::jsonb, $j$[]$j$::jsonb, false, 10),
  ('korea-number', 'Smartphone', 'active', $j${"mn":"Солонгост ашиглах дугаар холболт","en":"Korean phone number setup","ko":"한국 휴대폰 번호 개통"}$j$::jsonb, null, $j${"mn":"Солонгост очихоосоо өмнө холбоотой байхад зориулсан дугаар болон холболтын үйлчилгээ.","en":"A phone number and connectivity service so you can stay connected before you arrive in Korea.","ko":"한국에 도착하기 전부터 연결될 수 있도록 돕는 번호·통신 서비스입니다."}$j$::jsonb, $j${"mn":["Танд тохирох холболтын төрөл","Шаардлагатай бичиг баримт","Захиалах, хүлээн авах дараалал","Солонгост очсоны дараах ашиглалт"],"en":["Which connection type suits you","Documents you'll need","How ordering and pickup work","Using your number after you arrive"],"ko":["나에게 맞는 연결 방식","필요한 서류","신청 및 수령 절차","도착 후 이용 방법"]}$j$::jsonb, $j$[{"label":{"mn":"Оператор","en":"Carrier","ko":"통신사"},"value":null},{"label":{"mn":"Багц, үнэ","en":"Plans & pricing","ko":"요금제·가격"},"value":null},{"label":{"mn":"Дата хэмжээ","en":"Data allowance","ko":"데이터 제공량"},"value":null},{"label":{"mn":"Хүчинтэй хугацаа","en":"Validity","ko":"유효 기간"},"value":null},{"label":{"mn":"SIM / eSIM","en":"SIM / eSIM","ko":"SIM / eSIM"},"value":null},{"label":{"mn":"Төхөөрөмжийн нийцтэй байдал","en":"Device compatibility","ko":"기기 호환성"},"value":null}]$j$::jsonb, true, 20),
  ('translation', 'Languages', 'upcoming', $j${"mn":"Баталгаат орчуулга","en":"Certified translation","ko":"공증 번역"}$j$::jsonb, null, $j${"mn":"Суралцах, виз мэдүүлэхэд шаардлагатай бичиг баримтын баталгаат орчуулга.","en":"Certified translation of documents for study and visa applications.","ko":"유학 및 비자 신청에 필요한 서류의 공증 번역."}$j$::jsonb, $j${"mn":[],"en":[],"ko":[]}$j$::jsonb, $j$[]$j$::jsonb, false, 30),
  ('travel', 'Luggage', 'upcoming', $j${"mn":"Аялал жуулчлал","en":"Travel & tours","ko":"여행"}$j$::jsonb, null, $j${"mn":"Солонгос руу аялах, танилцах аялалд зориулсан үйлчилгээ.","en":"Services for trips and discovery tours to Korea.","ko":"한국 여행과 탐방을 위한 서비스."}$j$::jsonb, $j${"mn":[],"en":[],"ko":[]}$j$::jsonb, $j$[]$j$::jsonb, false, 40)
insert into public.faqs (question, answer, sort_order) values
  ($j${"mn":"Солонгос хэл огт мэдэхгүй хүн суралцаж болох уу?","en":"Can I join if I don't know any Korean?","ko":"한국어를 전혀 몰라도 수강할 수 있나요?"}$j$::jsonb, $j${"mn":"Анхан шатны сургалт нь Солонгос хэлийг эхнээс нь сурч буй хүмүүст зориулагдсан. Анги нээгдэх хуваарь болон дэлгэрэнгүйг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Our beginner course is meant for people starting Korean from scratch. Please check class schedules and details with a GuideOne advisor.","ko":"초급 과정은 한국어를 처음 배우는 분을 위한 과정입니다. 개강 일정과 자세한 내용은 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 10),
  ($j${"mn":"Сургалтын түвшинг хэрхэн тодорхойлох вэ?","en":"How is my course level determined?","ko":"수업 레벨은 어떻게 정하나요?"}$j$::jsonb, $j${"mn":"Энэ мэдээллийг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Please check this with a GuideOne advisor.","ko":"이 내용은 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 20),
  ($j${"mn":"TOPIK шалгалтад бэлтгэдэг үү?","en":"Do you offer TOPIK preparation?","ko":"TOPIK 시험 대비를 하나요?"}$j$::jsonb, $j${"mn":"TOPIK бэлтгэлийн сургалтын агуулга, хуваарийг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Please check the content and schedule of TOPIK preparation with a GuideOne advisor.","ko":"TOPIK 대비 과정의 내용과 일정은 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 30),
  ($j${"mn":"Солонгост суралцахын тулд ямар материал шаардлагатай вэ?","en":"What documents do I need to study in Korea?","ko":"한국 유학에는 어떤 서류가 필요한가요?"}$j$::jsonb, $j${"mn":"Шаардлагатай материал нь сургууль болон хөтөлбөрөөс (жишээ нь хэлний бэлтгэл эсвэл зэргийн хөтөлбөр) хамаарч өөр байдаг. Ерөнхийдөө гадаад паспорт, боловсролын баримт бичиг, санхүүгийн баталгаа зэрэг шаардагддаг. Танд хамаарах жагсаалтыг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Requirements differ by school and program (for example, a language program versus a degree program). Typically they include a passport, education documents and proof of finances. Please check the list that applies to you with a GuideOne advisor.","ko":"필요 서류는 학교와 과정(예: 어학연수, 학위 과정)에 따라 다릅니다. 일반적으로 여권, 학력 서류, 재정 증빙 등이 필요합니다. 본인에게 해당하는 목록은 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 40),
  ($j${"mn":"Сургууль сонгоход зөвлөгөө өгдөг үү?","en":"Do you help with choosing a school?","ko":"학교 선택에 대한 상담을 받을 수 있나요?"}$j$::jsonb, $j${"mn":"Тийм. GuideOne нь Солонгос дахь хамтран ажилладаг сургуулиуд руугаа суралцагчдыг зуучилдаг бөгөөд таны зорилго, сонирхолд тохирох сургууль, хөтөлбөрийг сонгоход тусална.","en":"Yes. GuideOne places students at its partner schools in Korea and helps you choose a school and program that fit your goals and interests.","ko":"네. GuideOne은 한국의 협력 학교로 유학을 연결하며, 목표와 관심에 맞는 학교와 프로그램 선택을 도와드립니다."}$j$::jsonb, 50),
  ($j${"mn":"Солонгос дугаар хэрхэн холбох вэ?","en":"How do I get a Korean phone number?","ko":"한국 번호는 어떻게 개통하나요?"}$j$::jsonb, $j${"mn":"Холболтын дараалал болон шаардлагатай материалын талаар GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Please check the steps and required documents with a GuideOne advisor.","ko":"개통 절차와 필요 서류는 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 60),
  ($j${"mn":"Солонгост ашиглах дугаар ямар төхөөрөмж дээр ажиллах вэ?","en":"Which devices does the Korean number work on?","ko":"한국 번호는 어떤 기기에서 사용할 수 있나요?"}$j$::jsonb, $j${"mn":"Энэ мэдээллийг GuideOne-ийн зөвлөхөөс тодруулна уу.","en":"Please check this with a GuideOne advisor.","ko":"이 내용은 GuideOne 상담사에게 문의해 주세요."}$j$::jsonb, 70);
